-- Verified ICE arrest city aggregates for the public /ice-alerts map.
--
-- Source: government data provided by ICE in response to a FOIA request,
-- processed by the Deportation Data Project, and analyzed by Indivisible
-- Fair Oaks-Carmichael. The release is CC0 1.0.
--
-- This migration is generated from src/data/ice-arrest-heatmap.json, the same
-- snapshot the static map renders. It contains every mapped city in the
-- release, not a sample: 8,599 rows
-- totalling 760,248 de-duplicated arrest
-- records. The source Parquet SHA-256 is recorded on the release row.
--
-- The map remains a static import because the release is immutable and the
-- 8,599-point client payload must not wait on a database round trip. The
-- database copy is the queryable backend record for operations and future
-- tooling; the two are generated from the same snapshot.

create table if not exists public.ice_heatmap_releases (
  id                      text primary key,
  generated_at            date not null,
  period_start            date not null,
  period_end              date not null,
  source_name             text not null,
  source_url              text not null,
  source_data_url         text not null,
  source_release          text not null,
  source_citation         text not null,
  license                 text not null,
  coordinate_source       text not null,
  coordinate_url          text not null,
  raw_records             bigint not null check (raw_records >= 0),
  duplicate_rows_removed  integer not null check (duplicate_rows_removed >= 0),
  records                 bigint not null check (records >= 0),
  records_with_us_city    bigint not null check (records_with_us_city >= 0),
  mapped_records          bigint not null check (mapped_records >= 0),
  unmapped_city_records   integer not null check (unmapped_city_records >= 0),
  records_without_usable_city bigint not null check (records_without_usable_city >= 0),
  mapped_cities           integer not null check (mapped_cities >= 1),
  mapped_share_of_city_tagged numeric(8, 6) not null
    check (mapped_share_of_city_tagged between 0 and 1),
  mapped_share_of_all     numeric(8, 6) not null check (mapped_share_of_all between 0 and 1),
  max_city_count          integer not null check (max_city_count >= 1),
  sha256                  text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  method                  text not null,
  release_checked_at      date not null,
  release_note            text not null,
  created_at              timestamptz not null default now(),
  check (period_end >= period_start),
  check (release_checked_at >= period_end)
);

create table if not exists public.ice_heatmap_cities (
  release_id   text not null references public.ice_heatmap_releases(id) on delete cascade,
  city         text not null check (length(trim(city)) > 0),
  state        text not null check (length(trim(state)) > 0),
  state_code   text not null check (state_code ~ '^[A-Z]{2}$'),
  lat          double precision not null check (lat between -90 and 90),
  lng          double precision not null check (lng between -180 and 180),
  arrest_count integer not null check (arrest_count > 0),
  primary key (release_id, state_code, city)
);

create index if not exists ice_heatmap_cities_count_idx
  on public.ice_heatmap_cities (release_id, arrest_count desc);

create index if not exists ice_heatmap_cities_state_idx
  on public.ice_heatmap_cities (release_id, state_code);

comment on table public.ice_heatmap_releases is
  'Verified national ICE arrest releases used by /ice-alerts. Public read; service-role writes only.';
comment on table public.ice_heatmap_cities is
  'City-level arrest totals from a verified ICE release. Coordinates are Census place points, not arrest addresses.';

alter table public.ice_heatmap_releases enable row level security;
alter table public.ice_heatmap_cities enable row level security;

drop policy if exists "Public can read ICE heatmap releases"
  on public.ice_heatmap_releases;
create policy "Public can read ICE heatmap releases"
  on public.ice_heatmap_releases for select
  to anon, authenticated
  using (true);

drop policy if exists "Public can read ICE heatmap cities"
  on public.ice_heatmap_cities;
create policy "Public can read ICE heatmap cities"
  on public.ice_heatmap_cities for select
  to anon, authenticated
  using (true);

revoke all on public.ice_heatmap_releases from anon, authenticated;
revoke all on public.ice_heatmap_cities from anon, authenticated;
grant select on public.ice_heatmap_releases to anon, authenticated;
grant select on public.ice_heatmap_cities to anon, authenticated;
grant all on public.ice_heatmap_releases to service_role;
grant all on public.ice_heatmap_cities to service_role;

insert into public.ice_heatmap_releases (
  id, generated_at, period_start, period_end, source_name, source_url,
  source_data_url, source_release, source_citation, license,
  coordinate_source, coordinate_url, raw_records, duplicate_rows_removed,
  records, records_with_us_city, mapped_records, unmapped_city_records,
  records_without_usable_city, mapped_cities, mapped_share_of_city_tagged,
  mapped_share_of_all, max_city_count, sha256, method, release_checked_at,
  release_note
) values (
  'ddp-ice-2026-08-06',
  '2026-11-14',
  '2022-10-01',
  '2026-08-06',
  'Deportation Data Project — processed ICE arrests',
  'https://deportationdata.org/data/processed/ice.html',
  'https://github.com/deportationdata/ice/blob/main/data/arrests-latest.parquet',
  'Latest available ICE enforcement release covers records through Aug. 6, 2026 (published Aug. 24, 2026; processed release updated Sept. 22, 2026).',
  'Government data provided by ICE in response to a FOIA request, processed by the Deportation Data Project, and analyzed by Indivisible Fair Oaks.',
  'CC0 1.0',
  'U.S. Census Bureau 2025 Gazetteer place internal points, with manual coordinates for selected cities and neighborhoods.',
  'https://www.census.gov/geographies/reference-files/2025/geo/gazetter-file.html',
  896393,
  10024,
  886369,
  778367,
  760248,
  18119,
  108002,
  8599,
  0.9767,
  0.8577,
  29537,
  '9aa0d48232805380057475c48d5953277c14307c6ddaef79b2ad28fb4d84a8a5',
  'De-duplicated individual arrest records grouped by the manually entered apprehension city and state, matched to Census place centroids. Counts are assigned to the city field, not street-level incident locations.',
  '2026-11-15',
  'Latest available ICE enforcement release checked Nov. 15, 2026; no newer release was available.'
)
on conflict (id) do update set
  generated_at = excluded.generated_at,
  period_start = excluded.period_start,
  period_end = excluded.period_end,
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  source_data_url = excluded.source_data_url,
  source_release = excluded.source_release,
  source_citation = excluded.source_citation,
  license = excluded.license,
  coordinate_source = excluded.coordinate_source,
  coordinate_url = excluded.coordinate_url,
  raw_records = excluded.raw_records,
  duplicate_rows_removed = excluded.duplicate_rows_removed,
  records = excluded.records,
  records_with_us_city = excluded.records_with_us_city,
  mapped_records = excluded.mapped_records,
  unmapped_city_records = excluded.unmapped_city_records,
  records_without_usable_city = excluded.records_without_usable_city,
  mapped_cities = excluded.mapped_cities,
  mapped_share_of_city_tagged = excluded.mapped_share_of_city_tagged,
  mapped_share_of_all = excluded.mapped_share_of_all,
  max_city_count = excluded.max_city_count,
  sha256 = excluded.sha256,
  method = excluded.method,
  release_checked_at = excluded.release_checked_at,
  release_note = excluded.release_note;

-- Replace any rows left by an earlier run of this immutable release so a
-- re-run leaves exactly the snapshot below.
delete from public.ice_heatmap_cities
where release_id = 'ddp-ice-2026-08-06';

